import{c as t,Q as o,j as a,m as l}from"./chunks/framework.COywXlYp.js";const p=JSON.parse('{"title":"3.3.0.22alpha4","description":"","frontmatter":{"title":"3.3.0.22alpha4","layout":"doc"},"headers":[],"relativePath":"en/updatelog/beta/3/33022a4.md","filePath":"en/updatelog/beta/3/33022a4.md"}'),i={name:"en/updatelog/beta/3/33022a4.md"};function n(d,e,r,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-3-0-22alpha4" tabindex="-1">3.3.0.22alpha4 <a class="header-anchor" href="#_3-3-0-22alpha4" aria-label="Permalink to &quot;3.3.0.22alpha4&quot;">​</a></h1><p>Release date: 2026/04/19</p><p>This is a development update. Upgraded from the original <code>3.2.1.20</code>, synchronized with the current <code>3.2.1.20</code> and <code>3.2.2.21</code></p><h2 id="update-content" tabindex="-1">Update content <a class="header-anchor" href="#update-content" aria-label="Permalink to &quot;Update content&quot;">​</a></h2><ul><li>Fix the following issues:</li><li><ul><li>In the inverted or dark mode, non-windows default style menu bar will display abnormally: the font is the current style, but the background is the system color.</li></ul></li><li><ul><li>In the inverted or dark mode, non-windows default style title bar may &quot;crash&quot;, the dark mode title bar is light color.</li></ul></li><li><ul><li>Clean cache cannot be cleaned</li></ul></li><li>Upgrade to Qt 6.11 version, fixing or adding some display:</li><li><ul><li>Now, the maximize button will hide or become lighter, just like the effect of 3.1.0 using Qt 6.9, not the effect of 6.10.</li></ul></li><li><ul><li>Added immersive rounded menu bar and dropdown box, not the straight-cornered dropdown box and the uncropped rounded menu bar.</li></ul></li><li>Adjust the lower limit of response delay to 50ms, to fix the &quot;crash&quot; problem of the title bar.</li><li>New product: <code>clickclean</code>, which has greatly simplified clickmouse, leaving only the clicker and its related settings, its update frequency is slower than clickmouse, and you need to manually check for updates.</li><li>Now, startup on boot will run in the background. If you are an older version user, you need to reset the startup on boot configuration in the settings to enable it.</li><li>Setting window icon changes to the clickmouse logo, not clickmouse logo with a setting icon.</li><li>Changed the <code>More settings</code> item description to <code>To enable or disable experimental features, click here.</code></li></ul><h2 id="clickclean-update-content" tabindex="-1">ClickClean update content <a class="header-anchor" href="#clickclean-update-content" aria-label="Permalink to &quot;ClickClean update content&quot;">​</a></h2><ul><li>Setting window icon changes to the clickmouse logo, not clickmouse logo with a setting icon.</li></ul><h2 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue description</th><th>Solution</th><th>Affected version</th><th>Fixed version</th><th>Status</th><th>Issue link</th></tr></thead><tbody><tr><td>None</td><td>None</td><td>None</td><td>None</td><td>None</td><td>None</td></tr></tbody></table><h2 id="download-link" tabindex="-1">Download link <a class="header-anchor" href="#download-link" aria-label="Permalink to &quot;Download link&quot;">​</a></h2><p><a href="https://github.com/xystudiocode/pyClickMouse/releases/tag/3.2.2.21" target="_blank" rel="noreferrer">Click to download</a></p>',11)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
